import {audit,companyName,calculate} from './engine.mjs';
import {defaultRules,fields,taxonomy} from './rules.mjs';
import {readWorkbook,reportXlsx} from './xlsx.mjs';

const $=s=>document.querySelector(s),esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const fmt=v=>v===null||v===undefined?'—':typeof v==='number'?new Intl.NumberFormat('en-IN',{maximumFractionDigits:3}).format(v):esc(v);
const path={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h6',book:'M4 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H3V3h1M13 6a3 3 0 0 1 3-3h5v16h-5a4 4 0 0 0-3 2',graph:'M12 3v6M5 15V9h14v6M2 15h6v6H2zM9 15h6v6H9zM16 15h6v6h-6z',clock:'M21 12a9 9 0 1 1-9-9 9 9 0 0 1 9 9M12 7v5l3 2',settings:'M4 7h16M4 17h16M8 4v6M16 14v6',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6zM8 12l3 3 5-6',upload:'M12 16V3M7 8l5-5 5 5M4 15v5h16v-5',download:'M12 3v13M7 11l5 5 5-5M4 16v5h16v-5',plus:'M12 5v14M5 12h14',check:'M5 12l4 4L19 6',alert:'M12 3 2 21h20zM12 9v5M12 17v1',info:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 11v6M12 7v1',arrow:'M5 12h14M14 7l5 5-5 5',lock:'M5 10h14v11H5zM8 10V6a4 4 0 0 1 8 0v4',search:'M19 19l-5-5M16 9a7 7 0 1 1-14 0 7 7 0 0 1 14 0',menu:'M3 6h18M3 12h18M3 18h18',chart:'M4 3v18h17M8 16v-5M13 16V7M18 16V4',layers:'m12 2 10 5-10 5L2 7zM2 12l10 5 10-5M2 17l10 5 10-5'};
const icon=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${path[n]||path.file}"/></svg>`;
const badge=s=>`<span class="badge ${esc(s.split(' ')[0])}">${esc(s)}</span>`;
const load=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
let state={page:'overview',reports:[],selected:0,books:[],rules:load('kpi.rules',structuredClone(defaultRules)),configs:load('kpi.configs',{}),history:[],keep:load('kpi.keep',false),severity:'All severities',category:'All categories',search:'',tablePage:0,patterns:[],inventory:[],busy:false};
let db;async function database(){if(db)return db;return new Promise((resolve,reject)=>{const q=indexedDB.open('kpi-audit-engine',1);q.onupgradeneeded=()=>q.result.createObjectStore('audits',{keyPath:'id'});q.onsuccess=()=>{db=q.result;resolve(db)};q.onerror=()=>reject(q.error);});}
async function history(action,value){const d=await database();return new Promise((resolve,reject)=>{const t=d.transaction('audits',action==='getAll'?'readonly':'readwrite'),s=t.objectStore('audits'),r=action==='put'?s.put(value):action==='delete'?s.delete(value):action==='clear'?s.clear():s.getAll();let result;r.onsuccess=()=>result=r.result;t.oncomplete=()=>resolve(result);t.onerror=()=>reject(t.error);});}
const current=()=>state.reports[state.selected];
const saveSettings=()=>{try{localStorage.setItem('kpi.rules',JSON.stringify(state.rules));localStorage.setItem('kpi.configs',JSON.stringify(state.configs));}catch{toast('Settings could not be saved in this browser.');}};
function toast(message){$('#toast').className='toast';$('#toast').textContent=message;setTimeout(()=>{$('#toast').className='';$('#toast').textContent='';},5500);}
const nav=[['overview','grid','Audit overview'],['workbooks','file','Workbook explorer'],['kpis','chart','KPI results'],['rules','book','KPI rulebook'],['dependencies','graph','Dependencies'],['history','clock','Audit history'],['settings','settings','Company settings']];
function render(){let r=current();$('#app').innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><div class="brandmark">${icon('layers')}</div><div><strong>KPI Audit Engine</strong><small>BY AB ASSOCIATES</small></div></div><div class="navlabel">Workspace</div>${nav.slice(0,3).map(n=>navItem(n)).join('')}<div class="navlabel">Governance</div>${nav.slice(3).map(n=>navItem(n)).join('')}<div class="sidebottom"><div class="privatebox"><b>${icon('lock').replace('<svg','<svg style="width:12px;height:12px;vertical-align:middle"')} Your data stays with you</b>Workbooks are processed locally in this browser. No AI transmission.</div><div class="profile"><div class="avatar">AB</div><div><b>AB Associates</b><small>Lean performance governance</small></div></div></div></aside><main class="main"><header class="topbar"><div><button class="btn small mobilemenu" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button> Workspace <span style="margin:0 10px;color:#c3c9bc">/</span> <strong>${nav.find(n=>n[0]===state.page)?.[2]}</strong></div><div class="topright"><span><i class="statusdot"></i>Local processing</span><span class="avatar">AB</span></div></header><div class="content">${pageContent()}<footer class="footer"><span>KPI Audit Engine <span style="margin:0 8px">·</span> Validate the numbers. Improve the decisions.</span><span>Deterministic engine v1.0</span></footer>${r?printReport(r):''}</div></main></div>`;bind();}
function navItem([id,ic,label]){return `<button class="navitem ${state.page===id?'active':''}" data-nav="${id}">${icon(ic)}${label}${id==='rules'?`<span class="navcount">${state.rules.length}</span>`:''}</button>`;}
function header(title,subtitle,actions=''){return `<div class="pagehead"><div><div class="eyebrow">Manufacturing intelligence</div><h1>${title}</h1><p class="sub">${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
const uploadBtn=()=>`<button class="btn primary" data-action="upload">${icon('plus')} New audit</button>`;
function tabs(){return state.reports.length?`<div class="filetabs">${state.reports.map((r,i)=>`<button class="filetab ${i===state.selected?'active':''}" data-tab="${i}">${esc(r.company)} <span class="fine">/ ${r.role}</span></button>`).join('')}</div>`:'';}
function pageContent(){switch(state.page){case'overview':return overview();case'workbooks':return explorer();case'kpis':return kpis();case'rules':return rulesPage();case'dependencies':return dependencies();case'history':return historyPage();case'settings':return settings();}}
function overview(){const r=current(),issues=r?.issues||[],counts=['Critical','Warning','Review Required'].map(s=>issues.filter(x=>x.severity===s).length);return header('Audit overview','A clear view of the numbers behind your Lean performance.',`${r?`<button class="btn" data-action="export">${icon('download')} Export report</button>`:''}${uploadBtn()}`)+tabs()+(!r?`<section class="hero"><div><div class="eyebrow">Confidence before conclusions</div><h2>Good decisions start with trustworthy KPIs.</h2><p>Validate workbook logic, trace source data, and separate spreadsheet issues from operational performance. Start with your Master and MCLS workbooks.</p><div class="chips"><span class="chip">Semantic KPI validation</span><span class="chip">Source-to-dashboard tracing</span><span class="chip">Private by design</span></div></div><div class="heroart">${icon('shield')}</div></section>`:`<div class="notice"><b>${esc(r.name)}</b><br>${r.pairedWith?`Paired with ${esc(r.pairedWith)}`:'Single workbook audit · upload the matching Master/MCLS pair for wider verification.'} <span style="float:right">${new Date(r.at).toLocaleString()}</span></div>`)+`<div class="sectionhead"><h2>Audit at a glance</h2><small>${r?'Root-cause groups · repeated occurrences combined':'Your results will appear after the first audit'}</small></div><div class="metrics">${metric('Critical findings',r?counts[0]:'—','Require correction','alert','red')}${metric('Warnings',r?counts[1]:'—','Data & governance checks','info','amber')}${metric('Review required',r?counts[2]:'—','Context or source verification','search','gold')}${metric('Verified checks',r?r.coverage.verified:'—','Supported deterministic checks','check','green')}</div><div class="grid2"><section class="card"><div class="cardhead"><h2>Data validation confidence</h2><span class="fine">${r?'Scoped result':'Awaiting workbook'}</span></div><div class="cardbody quality"><div class="ring"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="43" fill="none" stroke="#edf0e6" stroke-width="7"/><circle cx="50" cy="50" r="43" fill="none" stroke="#8da969" stroke-width="7" stroke-linecap="round" stroke-dasharray="${(r?.qualityScore||0)*2.702} 270.2"/></svg><div class="ringtext"><b>${r?.qualityScore!==null&&r?.qualityScore!==undefined?r.qualityScore+'%':'—'}</b><small>VALIDATED SCOPE</small></div></div><div style="flex:1"><strong>${r?'Coverage matters as much as the score.':'Trust is measured, not assumed.'}</strong><p>${r?r.scoreDefinition:'Unresolved imports and unsupported formulas stay unverified. Your data quality score is separate from operational performance.'}</p><div class="bar"><i style="width:${r?.coveragePercent||0}%"></i></div><div class="legend"><span>${r?.coveragePercent||0}% check coverage</span><span>${r?.coverage.blocked||0} blocked</span></div></div></div></section><section class="card"><div class="cardhead"><h2>From source to decision</h2><span class="pillcount">3 layers</span></div><div class="cardbody">${layer('file','Operational inputs','MCLS · monthly source data',r?'Mapped':'01')}${layer('settings','KPI calculations','Master · formulas & dependencies',r?`${r.kpis.length} KPIs`:'02')}${layer('chart','Governance & reporting','Targets · YTD · dashboard integrity',r?'Reviewed':'03')}</div></section></div><div class="sectionhead"><h2>Audit findings ${r?`<span class="pillcount">${issues.length}</span>`:''}</h2><small>${r?'Select a finding to explore its evidence':'Six distinct categories. One clear audit trail.'}</small></div><section class="card">${findings(r)}</section>`;}
function metric(label,value,foot,ic,color){return `<div class="metric ${color}"><div class="label">${label}${icon(ic)}</div><div class="num">${value}</div><div class="foot">${foot}</div></div>`;}
function layer(ic,title,sub,end){return `<div class="layer"><span class="layericon">${icon(ic)}</span><div><b>${title}</b><small>${sub}</small></div><span>${end}</span></div>`;}
function findings(r){if(!r)return `<div class="toolbar"><span class="fine">All findings</span></div><div class="tablewrap"><table><thead><tr><th>Severity</th><th>KPI / area</th><th>Category</th><th>Finding</th><th>Source</th></tr></thead></table></div><div class="empty">${icon('file')}<h3>Your first audit starts here</h3><p>Add one workbook or a matching Master + MCLS pair. We’ll map its structure and surface findings with traceable evidence.</p><button class="btn primary" data-action="upload">${icon('upload')} Upload workbooks</button></div>`;return `<div class="toolbar"><div class="search"><input id="search" type="search" placeholder="Search findings, KPIs or cells…" aria-label="Search findings" value="${esc(state.search)}"></div><select id="severity" aria-label="Filter severity">${options(['All severities','Critical','Warning','Review Required'],state.severity)}</select><select id="category" aria-label="Filter category">${options(['All categories',...taxonomy],state.category)}</select></div><div id="findingrows">${findingRows(r)}</div>`;}
function findingRows(r){let list=r.issues.filter(x=>(state.severity==='All severities'||x.severity===state.severity)&&(state.category==='All categories'||x.type===state.category)&&`${x.kpi} ${x.issue} ${x.sheet} ${x.location}`.toLowerCase().includes(state.search.toLowerCase()));let offset=state.tablePage*20,visible=list.slice(offset,offset+20);return `<div class="tablewrap"><table><thead><tr><th>Severity</th><th>KPI / area</th><th>Finding</th><th>Source</th><th>Occurrences</th><th></th></tr></thead><tbody>${visible.map(x=>`<tr class="clickable" tabindex="0" data-issue="${x.id}" aria-label="Open ${esc(x.kpi)} finding"><td>${badge(x.severity)}</td><td class="truncate"><strong>${esc(x.kpi)}</strong><small>${esc(x.type)}</small></td><td class="truncate"><strong>${esc(x.issue)}</strong><small>${esc(x.rule)}</small></td><td><strong>${esc(x.sheet)}</strong><small>${esc(x.location)}</small></td><td>${x.occurrences.length}${x.affectedCells?`<small>${x.affectedCells} cells</small>`:''}</td><td style="color:#91a17f">↗</td></tr>`).join('')}</tbody></table>${!visible.length?'<div class="emptycompact">No findings match these filters.</div>':''}</div><div class="tablefoot"><span>${list.length?offset+1:0}–${Math.min(offset+20,list.length)} of ${list.length} root-cause groups</span><div class="pagelinks"><button class="btn small" data-action="prev" ${offset===0?'disabled':''}>Previous</button><button class="btn small" data-action="next" ${offset+20>=list.length?'disabled':''}>Next</button></div></div>`;}
const options=(arr,value)=>arr.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('');
function noAudit(text='Run an audit to explore this view.'){return `<section class="card empty">${icon('file')}<h3>No workbook selected</h3><p>${text}</p>${uploadBtn()}</section>`;}
function explorer(){let r=current();return header('Workbook explorer','Understand the structure before evaluating the numbers.',uploadBtn())+tabs()+(!r?noAudit():`<div class="metrics">${metric('Workbook role',r.role,'Detected from structure','file','')}${metric('Sheets detected',r.sheets.length,'Including hidden sheets','layers','')}${metric('Formulas inspected',r.sheets.reduce((s,x)=>s+x.formulas,0).toLocaleString(),'Formula text preserved','settings','')}${metric('Imported formula cells',r.sheets.reduce((s,x)=>s+x.technical,0).toLocaleString(),'Grouped by source sheet','info','amber')}</div><div class="sectionhead"><h2>Sheet-role map</h2><small>Sheet names and content inform classification</small></div><section class="card tablewrap"><table><thead><tr><th>Sheet</th><th>Role</th><th>Dimensions</th><th>Formulas</th><th>Imported</th><th>Objects / metadata</th></tr></thead><tbody>${r.sheets.map(s=>`<tr><td><strong>${esc(s.name)}</strong><small>${esc(s.state)}</small></td><td><span class="chip">${s.role}</span></td><td>${s.rows} × ${s.cols}</td><td>${s.formulas}</td><td>${s.technical}</td><td><small>${s.merges} merges · ${s.charts} drawings/charts<br>${s.tables} tables · ${s.validations} validations · ${s.conditionalFormats} conditional formats</small></td></tr>`).join('')}</tbody></table></section><div class="sectionhead"><h2>Semantic input mapping</h2><small>Labels identify fields even when row positions change</small></div><section class="card tablewrap"><table><thead><tr><th>Field</th><th>Matched workbook label</th><th>Row</th></tr></thead><tbody>${Object.entries(r.inputMapping||{}).map(([k,v])=>`<tr><td>${esc(fields.find(f=>f.id===k)?.name||k)}</td><td>${esc(v.label)}</td><td>${v.row}</td></tr>`).join('')}</tbody></table></section>`);}
function spark(series){if(series.length<2)return '<div class="emptycompact">At least two verified periods are needed for a trend.</div>';let v=series.map(x=>x.expected),min=Math.min(...v),max=Math.max(...v),points=v.map((x,i)=>`${10+i/(v.length-1)*460},${65-(x-min)/(max-min||1)*52}`).join(' ');return `<svg class="spark" viewBox="0 0 480 80" role="img" aria-label="Computed monthly KPI trend"><path d="M10 66H470" stroke="#e6ebdf"/><polyline points="${points}" fill="none" stroke="#839f67" stroke-width="2" stroke-linejoin="round"/>${v.map((x,i)=>`<circle cx="${10+i/(v.length-1)*460}" cy="${65-(x-min)/(max-min||1)*52}" r="2.5" fill="#688850"><title>${series[i].period}: ${fmt(x)}</title></circle>`).join('')}</svg>`;}
function kpis(){let r=current();return header('KPI results','Independent calculations, reporting periods and source assumptions.',r?`<button class="btn" data-action="export">${icon('download')} Export</button>`:uploadBtn())+tabs()+(!r?noAudit():`<div class="notice">Computed values use mapped source inputs. “Verified” additionally confirms the Master formula result. Missing, invalid or unsupported inputs remain outside the verified scope.</div><div class="kpilist">${r.kpis.map(k=>`<section class="card"><div class="cardhead"><h2>${esc(k.name)}</h2><span class="chip">${esc(k.unit)}</span></div><div class="cardbody"><div class="legend"><span>${k.series.length} computed months</span><span>${k.blocked} blocked</span></div>${spark(k.series)}<div class="legend"><span>${k.series[0]?.period||'—'}</span><span>${k.series.at(-1)?.period||'—'}</span></div>${k.assumptions.length?`<div class="notice warn">Blank optional fields treated as zero: ${k.assumptions.map(x=>esc(fields.find(f=>f.id===x)?.name||x)).join(', ')}. Confirm applicability.</div>`:''}<div class="notice">${esc(k.aggregation)} ${k.aggregated!==null?`· all audited periods: <b>${fmt(k.aggregated)}</b>`:`· ${esc(k.aggregationNote)}`}</div><details><summary class="fine">Show monthly values and calculation status</summary><div class="tablewrap"><table><thead><tr><th>Period</th><th>Calculated</th><th>Saved result</th><th>Status</th></tr></thead><tbody>${k.series.map(s=>`<tr><td>${s.period}</td><td>${fmt(s.expected)}</td><td>${fmt(s.reported)}</td><td>${badge(s.status)}</td></tr>`).join('')}</tbody></table></div></details></div></section>`).join('')}</div>`);}
function rulesPage(){return header('KPI rulebook','Business definitions, calculation logic and governance in one place.',`<button class="btn" data-action="patterns">${icon('search')} Reference patterns</button><button class="btn primary" data-action="add-rule">${icon('plus')} Add KPI</button>`)+`<div class="notice">20 initial KPI definitions derived from the Entech architecture. Rules are editable in this browser. Formula changes are applied by rerunning the loaded audit; original workbooks are never changed.</div><div class="ruleslist">${state.rules.map(r=>`<section class="card rulecard"><div style="display:flex;justify-content:space-between"><span class="eyebrow">${esc(r.id)}</span>${badge(r.enabled?r.status:'Disabled')}</div><h3>${esc(r.name)}</h3><p>${esc(r.meaning)}</p><div class="code">${esc(r.formula)}</div><div class="rulemeta"><span>${esc(r.unit)} · ${r.direction} is better</span><span>${esc(r.frequency)}</span></div><div class="rulemeta"><span>${esc(r.aggregation)}</span></div><button class="btn small" data-rule="${esc(r.id)}">Edit definition ${icon('arrow')}</button></section>`).join('')}</div>`;}
function dependencies(){let r=current();return header('Dependencies','Trace source inputs through calculations to the management decision.')+`<div class="dependencygrid">${state.rules.filter(r=>r.enabled&&!r.record).map(rule=>`<section class="card depnode"><div class="eyebrow">${esc(rule.sheet)}</div><h2 style="margin-top:10px">${esc(rule.name)}</h2><div class="depin">${rule.inputs.map(i=>`<span class="chip">${esc(fields.find(f=>f.id===i)?.name||i)}</span>`).join('')}</div><div class="depout">↓ ${esc(rule.name)} → ${esc((rule.dependentKPIs||['Management reporting']).join(' · '))}</div></section>`).join('')}</div>${r?`<div class="sectionhead"><h2>Observed cross-sheet connections</h2><small>${r.dependencies.length} source-to-consumer connections</small></div><section class="card tablewrap"><table><thead><tr><th>Source sheet</th><th>Dependent sheet</th></tr></thead><tbody>${r.dependencies.map(x=>`<tr><td>${esc(x.from)}</td><td>${esc(x.to)}</td></tr>`).join('')}</tbody></table></section>`:''}`;}
function historyPage(){return header('Audit history','Saved reports on this device. Raw workbooks are never retained.',`<button class="btn danger" data-action="clear-history">Delete saved history</button>`)+`<section class="card"><div class="cardbody"><label class="inline"><input id="keep" type="checkbox" ${state.keep?'checked':''}> Save future audit reports in this browser</label><p class="fine">Off by default. Retained reports include findings and KPI values; they are not encrypted by this application. Use the device’s security controls. Reports expire after 30 days.</p></div></section><div class="sectionhead"><h2>Saved audits</h2><small>${state.history.length} reports</small></div><section class="card tablewrap"><table><thead><tr><th>Workbook</th><th>Audited</th><th>Findings</th><th>Scope coverage</th><th></th></tr></thead><tbody>${state.history.map(r=>`<tr><td><strong>${esc(r.company)}</strong><small>${esc(r.name)}</small></td><td>${new Date(r.at).toLocaleDateString()}</td><td>${r.issues.length}</td><td>${r.coveragePercent}%</td><td><button class="btn small" data-history="${r.id}">Open</button> <button class="btn small danger" data-delete="${r.id}">Delete</button></td></tr>`).join('')}</tbody></table>${!state.history.length?'<div class="emptycompact">No reports saved on this device.</div>':''}</section>`;}
function settings(){const companies=[...new Set([...state.reports.map(r=>r.company),...Object.keys(state.configs)])];let company=current()?.company||companies[0]||'';return header('Company settings','Keep company-specific targets and approved variations separate.',`<button class="btn" data-action="export-settings">${icon('download')} Export settings</button>`)+`<section class="card"><div class="cardhead"><h2>Company configuration</h2><button class="btn small" data-action="add-company">${icon('plus')} Add company</button></div><div class="cardbody"><label class="field"><span class="fine">Company</span><select id="company" class="companyselect">${options(companies,company)}</select></label><div class="notice">An override applies only to this company. Targets, benchmarks and thresholds are explicit inputs; a missed target is an operational observation, not a formula error.</div><div id="companytable">${companyTable(company)}</div></div></section><section class="card" style="margin-top:20px"><div class="cardhead"><h2>Data and access</h2></div><div class="cardbody"><ul class="checklist"><li><span>Workbook processing</span><b>Browser only</b></li><li><span>Raw workbook retention</span><b>Memory only · cleared on refresh</b></li><li><span>Audit history retention</span><b>Opt-in · 30 days</b></li><li><span>Hosted access</span><b>Owner-private Site</b></li><li><span>GitHub connection</span><b>geetahuja · access pending</b></li></ul><p class="fine">Team roles, PostgreSQL audit storage and encrypted server archival are not enabled in this browser edition. The source package includes a standalone API adapter.</p><button class="btn danger" data-action="clear-session">Clear loaded workbooks and results</button></div></section>`;}
function companyTable(company){if(!company)return '<div class="emptycompact">Add a company or run an audit to configure its rules.</div>';return `<div class="tablewrap"><table><thead><tr><th>KPI</th><th>Target</th><th>Benchmark</th><th>Change threshold</th><th>Enabled</th><th></th></tr></thead><tbody>${state.rules.map(r=>{let c=state.configs[company]?.[r.id]||{};return `<tr><td>${esc(r.name)}</td><td>${fmt(c.target??r.target)}</td><td>${fmt(c.benchmark??r.benchmark)}</td><td>${c.threshold??r.threshold}%</td><td>${(c.enabled??r.enabled)?'Yes':'No'}</td><td><button class="btn small" data-override="${r.id}" data-company="${esc(company)}">Configure</button></td></tr>`}).join('')}</tbody></table></div>`;}
function modal(title,body,footer=''){const previous=document.activeElement;$('#overlay').innerHTML=`<div class="modalbackdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalheader"><h2>${title}</h2><button class="close" aria-label="Close dialog" data-close>×</button></div><div class="modalbody">${body}</div>${footer?`<div class="modalfooter">${footer}</div>`:''}</section></div>`;$('#overlay').querySelector('[data-close]').onclick=()=>{if(state.busy)return;$('#overlay').innerHTML='';previous?.focus();};$('#overlay').querySelector('[data-close]').focus();$('#overlay').onkeydown=e=>{if(e.key==='Escape'&&!state.busy)$('#overlay').querySelector('[data-close]').click();if(e.key==='Tab'){let all=[...$('#overlay').querySelectorAll('button,input,select,textarea,a,summary')].filter(e=>!e.disabled);let first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};}
function uploadDialog(){modal('Start a new audit',`<p>Upload your manufacturing KPI workbooks. Select both <b>Master</b> and <b>MCLS</b> for a paired audit of each company.</p><button class="dropzone" id="drop">${icon('upload')}<b>Drop workbooks here, or browse files</b><small>.xlsx only · up to 20 MB each · maximum 6 files</small></button><div class="notice">Files are read locally. Source workbooks are never edited or uploaded to a server.</div><p class="fine">Supported reference families: Productivity, ROI, ITR, customer quality, production quality, OTD, OEE, Kaizen, savings, HR development, lead time and floor area.</p>`);$('#drop').onclick=()=>$('#files').click();$('#drop').ondragover=e=>{e.preventDefault();$('#drop').style.background='#edf3df';};$('#drop').ondrop=e=>{e.preventDefault();processFiles([...e.dataTransfer.files]);};}
async function processFiles(files){if(state.busy||!files.length)return;if(files.length>6){toast('Choose up to six workbooks per audit.');return;}state.busy=true;modal('Analyzing your workbooks',`<p id="progresslabel">Reading workbook structure…</p><div class="progress"></div><p class="fine">Deterministic checks run locally. Please keep this tab open.</p>`);let parsed=[];try{for(const file of files)parsed.push(await readWorkbook(file,s=>$('#progresslabel').textContent=s));$('#progresslabel').textContent='Validating inputs, formulas and dependencies…';await new Promise(r=>setTimeout(r,40));const output=audit(parsed,{rules:state.rules,patterns:state.patterns,companyConfigs:state.configs});state.books=parsed;state.reports=output.results;state.selected=0;state.page='overview';state.tablePage=0;state.search='';state.severity='All severities';state.category='All categories';if(state.keep){for(const r of output.results)await history('put',r);state.history=await history('getAll');}$('#overlay').innerHTML='';render();toast(`Audit complete · ${output.results.length} workbooks analyzed.`);}catch(e){modal('Workbook could not be analyzed',`<div class="errornotice">${esc(e.message)}</div><p>No source files were changed. Check the file format or size and try again.</p>`);}finally{state.busy=false;$('#files').value='';}}
function issueDialog(id){const r=current(),x=r.issues.find(x=>x.id===id);modal('Finding evidence',`${badge(x.severity)} <span class="fine" style="margin-left:10px">${x.id} · ${esc(x.type)}</span><h3 style="font-size:18px">${esc(x.kpi)}</h3><p>${esc(x.issue)}</p><div class="detailgrid"><div><small>Source sheet & location</small>${esc(x.sheet)} · ${esc(x.location)}</div><div><small>Period / occurrences</small>${esc(x.period)} · ${x.occurrences.length}</div><div><small>Saved / reported result</small>${fmt(x.reported)}</div><div><small>Expected independent result</small>${fmt(x.expected)}</div><div><small>Recalculated workbook result</small>${fmt(x.recalculated)}</div><div><small>Difference</small>${fmt(x.difference)}</div></div>${x.detectedFormula?`<h3>Detected formula</h3><div class="code">${esc(x.detectedFormula)}</div>`:''}${x.expectedLogic?`<h3>Expected business logic</h3><div class="code">${esc(x.expectedLogic)}</div>`:''}<h3>Root cause</h3><p>${esc(x.rootCause)}</p><h3>Downstream impact</h3><div class="chips">${x.impact.length?x.impact.map(s=>`<span class="chip">${esc(s)}</span>`).join(''):'<span class="fine">No additional impact established by this check.</span>'}</div><h3>Recommendation</h3><div class="notice">${esc(x.recommendation)}</div>${x.missing?`<h3>Missing inputs</h3><div class="code">${x.missing.map(m=>`${esc(m.period)}: ${m.fields.map(f=>esc(fields.find(x=>x.id===f)?.name||f)).join(', ')}`).join('\n')}</div>`:''}<details><summary class="fine">All occurrences / cell locations</summary><div class="code">${x.occurrences.map(o=>`${esc(o.period)} · ${esc(o.location)} · reported ${fmt(o.reported)} · expected ${fmt(o.expected)}`).join('\n')}${x.locations?'\n'+x.locations.map(esc).join(', '):''}</div></details>`);}
function inputField(label,name,value,type='text',full=false){return `<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value??'')}" ${type==='number'?'step="any"':''}></div>`;}
function editRule(id,company=null){const original=state.rules.find(r=>r.id===id)||{...structuredClone(defaultRules[0]),id:'custom-'+Date.now().toString(36),name:'Custom KPI',formula:'sales',inputs:['sales'],meaning:'',optional:[],sheet:'',dependentKPIs:[],status:'Candidate'};let r={...original,...(company?state.configs[company]?.[id]:{})};modal(company?'Company override':'KPI definition',`<form id="ruleform"><div class="formgrid">${company?`<div class="field full"><b>${esc(company)} · ${esc(r.name)}</b></div>`:inputField('KPI name','name',r.name)}${!company?inputField('Business meaning','meaning',r.meaning,'text',true):''}${inputField('Source calculation sheet','sheet',r.sheet)}${inputField('Unit','unit',r.unit)}${inputField('Monthly output occurrence (0 = first)','outputOccurrence',r.outputOccurrence??0,'number')}<div class="field"><label for="f-direction">Direction of good</label><select id="f-direction" name="direction">${options(['Higher','Lower'],r.direction)}</select></div>${inputField('Target (blank = not configured)','target',r.target,'number')}${inputField('Benchmark (blank = not configured)','benchmark',r.benchmark,'number')}${inputField('Change warning threshold (%)','threshold',r.threshold,'number')}<div class="field"><label for="f-aggregation">Aggregation</label><select id="f-aggregation" name="aggregation">${options(['SUM','AVERAGE','WEIGHTED AVERAGE','RATIO OF TOTALS','LAST VALUE','MIN','MAX','CUSTOM FORMULA'],r.aggregation)}</select></div>${inputField('Formula (use input identifiers)','formula',r.formula,'text',true)}${inputField('Input identifiers, comma-separated','inputs',r.inputs.join(', '),'text',true)}${inputField('Optional inputs (blank counts as zero)','optional',(r.optional||[]).join(', '),'text',true)}${inputField('Aliases, comma-separated','aliases',(r.aliases||[]).join(', '),'text',true)}${inputField('Downstream KPIs, comma-separated','dependentKPIs',(r.dependentKPIs||[]).join(', '),'text',true)}${inputField('Cumulative numerator field','numerator',r.numerator||'')}${inputField('Cumulative denominator field','denominator',r.denominator||'')}${inputField('Ratio multiplier','multiplier',r.multiplier??1,'number')}${inputField('Weight field (weighted average)','weightField',r.weightField||'')}</div><label class="inline"><input type="checkbox" name="enabled" ${r.enabled?'checked':''}> Enable this KPI</label><div class="notice">Available source identifiers: ${fields.map(f=>`<code>${f.id}</code>`).join(', ')}. Unsupported expressions are rejected; no arbitrary code is executed.</div><div id="formerror" role="alert"></div></form>`,`<button class="btn primary" id="saverule">${company?'Save override':'Approve and save rule'}</button>`);$('#saverule').onclick=()=>{let f=new FormData($('#ruleform')),get=k=>f.get(k),split=k=>String(get(k)||'').split(',').map(x=>x.trim()).filter(Boolean);let changes={outputOccurrence:+get('outputOccurrence'),sheet:get('sheet'),unit:get('unit'),direction:get('direction'),target:get('target')===''?null:+get('target'),benchmark:get('benchmark')===''?null:+get('benchmark'),threshold:+get('threshold'),aggregation:get('aggregation'),formula:get('formula'),inputs:split('inputs'),optional:split('optional'),aliases:split('aliases'),dependentKPIs:split('dependentKPIs'),numerator:get('numerator'),denominator:get('denominator'),multiplier:+get('multiplier'),weightField:get('weightField'),enabled:get('enabled')==='on',status:'Approved'};try{if(!changes.formula||!changes.inputs.length)throw Error('Provide a formula and its inputs.');const valid=new Set([...fields.map(f=>f.id),'people','hours','shipment','order']);if(changes.inputs.some(x=>!valid.has(x)))throw Error('Use recognized input identifiers.');if(changes.optional.some(x=>!changes.inputs.includes(x)))throw Error('Optional inputs must be included in the input list.');if(changes.aggregation==='RATIO OF TOTALS'&&(!changes.inputs.includes(changes.numerator)||!changes.inputs.includes(changes.denominator)))throw Error('Ratio aggregation needs valid numerator and denominator input identifiers.');if(changes.aggregation==='WEIGHTED AVERAGE'&&!changes.inputs.includes(changes.weightField))throw Error('Choose a weight field from the inputs.');if(!Number.isInteger(changes.outputOccurrence)||changes.outputOccurrence<0)throw Error('Output occurrence must be a nonnegative integer.');if(changes.threshold<0)throw Error('The change threshold must be nonnegative.');calculate(changes.formula,Object.fromEntries(changes.inputs.map((x,i)=>[x,i+2])));if(company){state.configs[company]??={};state.configs[company][id]=changes;}else{changes.name=get('name');changes.meaning=get('meaning');let idx=state.rules.findIndex(x=>x.id===id);const next={...original,...changes};if(idx<0)state.rules.push(next);else state.rules[idx]=next;}saveSettings();$('#overlay').innerHTML='';render();toast('Rule saved. Rerun the audit to apply it to current results.');}catch(e){$('#formerror').className='errornotice';$('#formerror').textContent=e.message;}};}
function exportDialog(){const r=current();modal('Export audit report',`<p>Download the findings with source locations, expected values, root causes and recommendations.</p><div class="actions" style="flex-wrap:wrap"><button class="btn primary" id="xlsxexport">${icon('download')} Excel report</button><button class="btn" id="jsonexport">JSON evidence</button><button class="btn" id="csvexport">CSV findings</button><button class="btn" id="pdfexport">Print / save PDF</button></div><div class="notice">The report includes blocked checks and coverage limitations. Source workbooks remain unchanged.</div>`);$('#xlsxexport').onclick=async()=>{download(await reportXlsx(r),`KPI-Audit-${r.company}.xlsx`);toast('Excel report downloaded.');};$('#jsonexport').onclick=()=>download(JSON.stringify(r,null,2),`KPI-Audit-${r.company}.json`,'application/json');$('#csvexport').onclick=()=>{const keys=['id','severity','kpi','type','period','sheet','location','issue','reported','expected','difference','rule','rootCause','impact','recommendation'];const safe=v=>{v=Array.isArray(v)?v.join('; '):String(v??'');if(/^[=+\-@\t\r]/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"';};download([keys.map(safe).join(','),...r.issues.map(x=>keys.map(k=>safe(x[k])).join(','))].join('\r\n'),`KPI-Audit-${r.company}.csv`,'text/csv');};$('#pdfexport').onclick=()=>{$('#overlay').innerHTML='';window.print();};}
function download(content,name,type='application/octet-stream'){const b=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function printReport(r){return `<article class="printonly"><div class="eyebrow">AB Associates · Lean performance governance</div><h1>KPI Audit Report</h1><p><b>${esc(r.name)}</b> · ${new Date(r.at).toLocaleString()}</p><h2>Executive summary</h2><p>${r.issues.filter(x=>x.severity==='Critical').length} critical groups · ${r.issues.filter(x=>x.severity==='Warning').length} warnings · ${r.issues.filter(x=>x.severity==='Review Required').length} review groups. ${r.coverage.verified} checks verified; ${r.coverage.failed} failed; ${r.coverage.blocked} blocked. Validation confidence: ${r.qualityScore??'N/A'}%; scope coverage: ${r.coveragePercent}%.</p><p>${esc(r.scoreDefinition)}</p><h2>Audit scope and coverage</h2><p>${esc(r.scope.join('; '))}</p><p>${esc(r.limitations.join(' '))}</p><h2>Findings, root causes and recommendations</h2><table><thead><tr><th>ID / severity</th><th>KPI / category</th><th>Finding / source</th><th>Reported / expected</th><th>Impact and recommendation</th></tr></thead><tbody>${r.issues.map(x=>`<tr><td>${x.id}<br>${x.severity}</td><td>${esc(x.kpi)}<br>${esc(x.type)}</td><td>${esc(x.issue)}<br>${esc(x.sheet)}!${esc(x.location)} · ${esc(x.period)}<br>${x.occurrences.length} occurrences</td><td>${fmt(x.reported)} / ${fmt(x.expected)}</td><td>${esc(x.impact.join(', '))}<br>${esc(x.recommendation)}</td></tr>`).join('')}</tbody></table></article>`;}
function patternsDialog(){modal('Reference-derived formula candidates',`<p>Extracted from the Entech workbooks. A candidate is not automatically enforced as a business rule. Review the definition before adding or approving a KPI.</p><div class="tablewrap"><table><thead><tr><th>Sheet / business label</th><th>Formula example</th></tr></thead><tbody>${state.patterns.slice(0,150).map(p=>`<tr><td><strong>${esc(p.sheet)}</strong>${esc(p.label)}<small>${esc(p.unit)}</small></td><td><code>${esc(p.examples[0]?.formula)}</code></td></tr>`).join('')}</tbody></table></div>`,`<button class="btn" id="downloadpatterns">Download all ${state.patterns.length} candidates</button><button class="btn primary" id="candidateadd">Add approved KPI definition</button>`);$('#downloadpatterns').onclick=()=>download(JSON.stringify(state.patterns,null,2),'Entech-reference-formula-candidates.json','application/json');$('#candidateadd').onclick=()=>editRule(null);}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{state.page=b.dataset.nav;render()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.selected=+b.dataset.tab;state.tablePage=0;render()});bindFindings();document.querySelectorAll('[data-rule]').forEach(b=>b.onclick=()=>editRule(b.dataset.rule));bindOverrides();document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{state.reports=[state.history.find(x=>x.id===b.dataset.history)];state.selected=0;state.books=[];state.page='overview';render()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{await history('delete',b.dataset.delete);state.history=await history('getAll');render()});if($('#keep'))$('#keep').onchange=e=>{state.keep=e.target.checked;localStorage.setItem('kpi.keep',JSON.stringify(state.keep));toast(state.keep?'Future audit reports will be saved on this device.':'Future audit reports will remain in memory only.');};if($('#company'))$('#company').onchange=e=>{$('#companytable').innerHTML=companyTable(e.target.value);bindOverrides();};if($('#search'))$('#search').oninput=e=>{state.search=e.target.value;state.tablePage=0;refreshFindings()};for(const id of ['severity','category'])if($('#'+id))$('#'+id).onchange=e=>{state[id]=e.target.value;state.tablePage=0;refreshFindings()};bindActions();}
function bindOverrides(){document.querySelectorAll('[data-override]').forEach(b=>b.onclick=()=>editRule(b.dataset.override,b.dataset.company));}
function bindFindings(){document.querySelectorAll('[data-issue]').forEach(b=>{b.onclick=()=>issueDialog(b.dataset.issue);b.onkeydown=e=>{if(e.key==='Enter')issueDialog(b.dataset.issue)}});}
function refreshFindings(){$('#findingrows').innerHTML=findingRows(current());bindFindings();bindActions();}
function bindActions(){document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{switch(b.dataset.action){case'upload':uploadDialog();break;case'export':exportDialog();break;case'menu':$('.sidebar').classList.toggle('open');break;case'add-rule':editRule(null);break;case'patterns':patternsDialog();break;case'prev':state.tablePage--;refreshFindings();break;case'next':state.tablePage++;refreshFindings();break;case'export-settings':download(JSON.stringify({rules:state.rules,companies:state.configs},null,2),'KPI-rulebook-and-company-settings.json','application/json');break;case'clear-history':await history('clear');state.history=[];render();toast('Saved audit history deleted from this browser.');break;case'clear-session':state.books=[];state.reports=[];state.selected=0;render();toast('Loaded workbooks and current results cleared.');break;case'add-company':modal('Add company',`<div class="field"><label for="newcompany">Exact company name (as used before G12 in the workbook filename)</label><input id="newcompany" placeholder="Company name"></div>`,`<button class="btn primary" id="savecompany">Add company</button>`);$('#savecompany').onclick=()=>{const name=$('#newcompany').value.trim();if(!name){toast('Enter a company name.');return;}state.configs[name]??={};saveSettings();$('#overlay').innerHTML='';render();};break;}});}
$('#files').onchange=e=>processFiles([...e.target.files]);
try{state.patterns=await fetch('/reference-patterns.json').then(r=>r.json());}catch{toast('Reference patterns could not load. Core KPI checks are available.');}
try{const reports=await history('getAll');for(const r of reports){if(Date.now()-Date.parse(r.at)>30*864e5)await history('delete',r.id);else state.history.push(r);}}catch{state.keep=false;}
render();
